parameters.jsCode:
// Fallback (standalone) client-config resolver.
// Finds the registry row whose client_id matches the incoming envelope and maps
// its Notion properties into the shared client_config object. When this module is
// called by the orchestrator, client_config is already present and this branch is skipped.
const trigger = $('Execute Workflow Trigger').first().json;
const wantId = trigger.client_id;
const rows = $input.all();

// The n8n Notion node flattens properties as 'property_<snake_cased_name>' (e.g. 'Client Name'
// -> property_client_name). Try that form as well as the raw name for robustness.
function prop(props, name) {
  const keys = [name, 'property_' + name, 'property_' + String(name).toLowerCase().replace(/ /g, '_')];
  let p;
  for (const k of keys) { const v = props && props[k]; if (v !== undefined && v !== null) { p = v; break; } }
  if (p === undefined || p === null) return null;
  if (typeof p === 'string') return p;
  return p.value ?? p.name ?? p.email ?? p.checkbox ?? p.text ?? p ?? null;
}

let match = null;
for (const r of rows) {
  const props = r.json.properties || r.json;
  if (prop(props, 'client_id') === wantId) { match = props; break; }
}
if (!match) {
  throw new Error(`No client registry row found for client_id='${wantId}'`);
}

const client_config = {
  client_id: wantId,
  client_name: prop(match, 'Client Name'),
  status: prop(match, 'Client Status'),
  service_tier: prop(match, 'service_tier'),
  commercial_contact_email: prop(match, 'commercial_contact_email'),
  templates: { en: prop(match, 'template_id_en'), es: prop(match, 'template_id_es') },
  proposals_folder_id: prop(match, 'proposals_folder_id'),
  reference_docs_folder_id: prop(match, 'reference_docs_folder_id'),
  pricing_sheet_id: prop(match, 'pricing_sheet_id'),
  notification_chat_id: prop(match, 'notification_chat_id')
};

return [{ json: { client_id: wantId, client_config, data: trigger.data, status: 'ok', errors: [] } }];

